#!/usr/bin/env bash
# AZ-5 — DTFS release builder.
#
# Turns a version string into a publishable GitHub release: builds the
# four binaries with the version stamped in (DTFS_VERSION, CLAUDE.md
# § A.3.5), assembles the fixed-name asset the updater downloads, writes
# checksums, and prints (or runs, with --publish) the
# `gh release create` command. Release notes: generated by `git-cliff`
# from commit subjects/trailers (`.github/cliff.toml`) into `notes.md`,
# passed via `--notes-file`, when `git-cliff` is installed; otherwise the
# release gets a one-line body. .github/workflows/release.yml builds with
# this script, then signs and publishes with the same `gh release create`
# shape (plus the notes it generates itself).
#
# Usage:
#   ./scripts/dtfs-release.sh <version> [--publish]
#   ./scripts/dtfs-release.sh v0.3.0
#   ./scripts/dtfs-release.sh v0.3.0 --publish
#
# Output: $CARGO_TARGET_DIR (default target)/release-artifacts/<version>/
#   dtfs-linux-amd64.tar.gz   asset the updater pulls (dtfs/bin + systemd + MANIFEST)
#   SHA256SUMS                checksum of the asset
#   notes.md                  git-cliff-generated release notes (if git-cliff ran)
#   SHA256SUMS.minisig        only if present (scripts/ci/sign-release.sh) when publishing
#
# Exit codes: 0 ok, 1 build/assembly failed, 3 invalid argument.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
PROJECT_ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"
cd "$PROJECT_ROOT"

if [ -t 1 ]; then
    GREEN='\033[0;32m'; YELLOW='\033[0;33m'; RED='\033[0;31m'; BOLD='\033[1m'; OFF='\033[0m'
else
    GREEN=''; YELLOW=''; RED=''; BOLD=''; OFF=''
fi
info()  { echo -e "${GREEN}[INFO]${OFF}  $*"; }
warn()  { echo -e "${YELLOW}[WARN]${OFF}  $*"; }
error() { echo -e "${RED}[ERROR]${OFF} $*"; }
step()  { echo -e "\n${BOLD}>>> $*${OFF}"; }

VERSION=""
PUBLISH=0

while [ $# -gt 0 ]; do
    case "$1" in
        --publish) PUBLISH=1 ;;
        --help|-h) sed -n '2,24p' "$0"; exit 0 ;;
        -*) error "unknown flag: $1"; exit 3 ;;
        *)
            if [ -z "$VERSION" ]; then VERSION="$1"; else
                error "unexpected argument: $1"; exit 3
            fi
            ;;
    esac
    shift
done

[ -n "$VERSION" ] || { error "missing <version> (e.g. v0.3.0)"; exit 3; }
if ! echo "$VERSION" | grep -qE '^v[0-9]+\.[0-9]+\.[0-9]+'; then
    warn "version '$VERSION' doesn't look like vX.Y.Z — using it as-is"
fi
# Stamp the version + a fresh build date into the binaries (§ A.3.5), then
# build + stage the canonical tarball via dtfs-build.sh.
export DTFS_VERSION="$VERSION"
export SOURCE_DATE_EPOCH="$(date -u +%s)"

step "Building + staging $VERSION"
"$SCRIPT_DIR/dtfs-build.sh"

TARGET_ROOT="${CARGO_TARGET_DIR:-$PROJECT_ROOT/target}"
SRC_TARBALL="$(ls -t "$TARGET_ROOT"/dist/dtfs-*-linux-amd64.tar.gz 2>/dev/null | head -1 || true)"
[ -n "$SRC_TARBALL" ] && [ -f "$SRC_TARBALL" ] || { error "dtfs-build.sh produced no tarball"; exit 1; }

OUT_DIR="$TARGET_ROOT/release-artifacts/$VERSION"
ASSET="dtfs-linux-amd64.tar.gz"
step "Assembling release artifacts in $OUT_DIR"
rm -rf "$OUT_DIR"
mkdir -p "$OUT_DIR"
cp "$SRC_TARBALL" "$OUT_DIR/$ASSET"
( cd "$OUT_DIR" && sha256sum "$ASSET" > SHA256SUMS )

# Confirm the version stamp survived into the asset (§ A.3.5).
step "Verifying version stamp"
TMP="$(mktemp -d)"; trap 'rm -rf "$TMP"' EXIT
tar -C "$TMP" -xzf "$OUT_DIR/$ASSET" dtfs/bin/dtfs-cli
STAMP="$("$TMP/dtfs/bin/dtfs-cli" --version 2>/dev/null || true)"
case "$STAMP" in
    "dtfs-cli $VERSION "*) info "stamp OK: $STAMP" ;;
    *) error "version stamp mismatch: expected 'dtfs-cli $VERSION ...', got '$STAMP'"; exit 1 ;;
esac

# Release notes from commit subjects/trailers (.github/cliff.toml), when
# git-cliff is installed (an operator/CI concern; not installed here).
NOTES_ARGS=(--notes "Build $VERSION")
if command -v git-cliff >/dev/null 2>&1; then
    step "Generating release notes with git-cliff"
    if git-cliff --config "$PROJECT_ROOT/.github/cliff.toml" --tag "$VERSION" --unreleased --strip header -o "$OUT_DIR/notes.md"; then
        info "wrote $OUT_DIR/notes.md"
        NOTES_ARGS=(--notes-file "$OUT_DIR/notes.md")
    else
        warn "git-cliff failed; release gets a one-line body"
    fi
else
    warn "git-cliff not found; release gets a one-line body (see https://git-cliff.org)"
fi
ASSETS=("$OUT_DIR/$ASSET" "$OUT_DIR/SHA256SUMS")
[ ! -f "$OUT_DIR/SHA256SUMS.minisig" ] || ASSETS+=("$OUT_DIR/SHA256SUMS.minisig")
GH_CMD=(gh release create "$VERSION" "${ASSETS[@]}" --title "$VERSION" --target "$(git rev-parse HEAD)" "${NOTES_ARGS[@]}")

step "Release artifacts"
ls -lh "$OUT_DIR"
echo

if [ "$PUBLISH" -eq 1 ]; then
    command -v gh >/dev/null 2>&1 || { error "gh not found; cannot --publish"; exit 1; }
    step "Publishing with gh"
    if gh release view "$VERSION" >/dev/null 2>&1; then
        error "release $VERSION already exists; refusing to overwrite"; exit 1
    fi
    "${GH_CMD[@]}"
    info "published $VERSION"
else
    info "Not publishing (no --publish). To create the GitHub release, run:"
    printf '    %q' "${GH_CMD[@]}"; echo
fi
